package net.civeira.phylax.features.access.dcrinitialaccesstoken.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class AllowedGrantTypesVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property allowed grant types of dcr initial access token ")
  void test_allowed_grant_types_v_o_builder() {
    Assertions.assertFalse(AllowedGrantTypesVO.nullValue().getAllowedGrantTypes().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(AllowedGrantTypesVO.tryFrom(null).getAllowedGrantTypes().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one",
        AllowedGrantTypesVO.from("one").getAllowedGrantTypes().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> AllowedGrantTypesVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", AllowedGrantTypesVO.from("one").toString());
  }
}
